import networkx as nx
import json
import os
import math
import heapq
import pandas as pd
from typing import Dict, List


def _edge_cost(data):
    value = data.get("cost")
    if value is None:
        return None
    try:
        value = float(value)
        return value if math.isfinite(value) and value >= 0 else None
    except (TypeError, ValueError):
        return None


def _edge_union_cost(G, edges):
    return sum(_edge_cost(G[u][v]) or 0.0 for u, v in edges)


def _shortest_paths(h, src, dsts):
    paths = {}
    for dst in dsts:
        paths[dst] = nx.dijkstra_path(h, src, dst, weight="cost")
    return paths


def _paths_to_edges(paths):
    result = set()
    for path in paths.values():
        result.update(zip(path, path[1:]))
    return result


def _greedy_tree(h, src, terminals, orders):
    """Build up to four gateway-based exact multicast clusters with a greedy fallback."""
    terminals = list(dict.fromkeys(terminals))
    if not terminals:
        return set(), {}

    # Source shortest paths provide deterministic first-transit clustering and
    # reusable source-side reachability information.
    try:
        lengths, source_paths = nx.single_source_dijkstra(h, src, weight="cost")
    except (nx.NetworkXNoPath, nx.NodeNotFound):
        lengths, source_paths = {}, {}

    reachable = [t for t in terminals if t in source_paths]
    if len(reachable) != len(terminals):
        return None, None

    buckets = {}
    for terminal in reachable:
        path = source_paths[terminal]
        first_hop = path[1] if len(path) > 1 else terminal
        buckets.setdefault(first_hop, []).append(terminal)

    # Preserve locality where possible, then cap the number of independent
    # multicast cores. Round-robin assignment avoids oversized clusters.
    ordered = []
    for key in sorted(buckets, key=lambda x: (lengths.get(x, float("inf")), str(x))):
        ordered.extend(sorted(buckets[key], key=str))

    cluster_count = min(4, max(1, math.ceil(len(ordered) / 7)))
    clusters = [[] for _ in range(cluster_count)]
    for index, terminal in enumerate(ordered):
        clusters[index % cluster_count].append(terminal)

    if any(len(cluster) > 7 for cluster in clusters):
        clusters = [ordered[i:i + 7] for i in range(0, len(ordered), 7)]

    selected = set()
    selected_paths = {}
    for cluster in clusters:
        if not cluster:
            continue

        candidates = sorted(
            (node for node in source_paths if node != src),
            key=lambda node: (lengths.get(node, float("inf")), str(node)),
        )[:8]
        if src not in candidates:
            candidates.insert(0, src)

        best_cluster_edges = None
        best_cluster_cost = float("inf")
        best_gateway = None

        for gateway in candidates:
            try:
                gateway_paths = nx.single_source_dijkstra_path(
                    h, gateway, weight="cost"
                )
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                continue
            if any(dst not in gateway_paths for dst in cluster):
                continue

            subtree = _directed_steiner_edges(h, gateway, cluster)
            if subtree is None:
                continue

            prefix = set(zip(source_paths[gateway], source_paths[gateway][1:]))
            candidate_edges = prefix | subtree
            candidate_cost = _edge_union_cost(h, candidate_edges)
            if candidate_cost < best_cluster_cost:
                best_cluster_cost = candidate_cost
                best_cluster_edges = candidate_edges
                best_gateway = gateway

        if best_cluster_edges is None:
            return None, None

        selected.update(best_cluster_edges)
        for dst in cluster:
            try:
                selected_paths[dst] = nx.dijkstra_path(
                    nx.edge_subgraph(h, selected).copy(),
                    src,
                    dst,
                    weight="cost",
                )
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                # Paths are reconstructed after all cluster edges are merged.
                selected_paths[dst] = None

    tree = nx.edge_subgraph(h, selected).copy()
    for dst in terminals:
        try:
            selected_paths[dst] = nx.dijkstra_path(tree, src, dst, weight="cost")
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            selected_paths[dst] = None

    if all(selected_paths.get(dst) for dst in terminals):
        return selected, selected_paths

    # Feasible bounded fallback for unusually large or structurally difficult
    # terminal sets.
    best_edges = None
    best_paths = None
    best_cost = float("inf")
    for order in orders:
        used = set()
        paths = {}
        feasible = True
        for dst in order:
            def marginal(u, v, data):
                if (u, v) in used:
                    return 0.0
                cost = _edge_cost(data)
                return float("inf") if cost is None else cost

            try:
                path = nx.dijkstra_path(h, src, dst, weight=marginal)
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                feasible = False
                break
            paths[dst] = path
            used.update(zip(path, path[1:]))

        if feasible:
            value = _edge_union_cost(h, used)
            if value < best_cost:
                best_cost = value
                best_edges = used
                best_paths = paths

    return best_edges, best_paths


def _directed_steiner_edges(h, src, terminals):
    """
    Exact directed Steiner DP for a small terminal set.
    dp[mask][v] is represented by a cost dictionary and traceback dictionary.
    """
    terminals = list(dict.fromkeys(terminals))
    k = len(terminals)
    if k == 0:
        return set()
    if k > 7:
        return None

    nodes = list(h.nodes())
    incoming = {v: [] for v in nodes}
    for u, v, data in h.edges(data=True):
        c = _edge_cost(data)
        if c is not None:
            incoming[v].append((u, c))

    full = (1 << k) - 1
    dp = [dict() for _ in range(full + 1)]
    choice = [dict() for _ in range(full + 1)]

    for mask in range(1, full + 1):
        initial = {}
        initial_choice = {}

        if mask & (mask - 1) == 0:
            terminal = terminals[mask.bit_length() - 1]
            initial[terminal] = 0.0
            initial_choice[terminal] = ("terminal",)
        else:
            sub = (mask - 1) & mask
            while sub:
                other = mask ^ sub
                if other and sub < other:
                    common = set(dp[sub]).intersection(dp[other])
                    for v in common:
                        value = dp[sub][v] + dp[other][v]
                        if value < initial.get(v, float("inf")):
                            initial[v] = value
                            initial_choice[v] = ("merge", sub)
                sub = (sub - 1) & mask

        # Multi-source reverse Dijkstra computes min_w c(v,w) + initial[w].
        dist = dict(initial)
        trace = dict(initial_choice)
        heap = [(value, v) for v, value in initial.items()]
        heapq.heapify(heap)

        while heap:
            value, v = heapq.heappop(heap)
            if value != dist.get(v):
                continue
            for u, edge_cost in incoming.get(v, []):
                candidate = value + edge_cost
                if candidate < dist.get(u, float("inf")):
                    dist[u] = candidate
                    trace[u] = ("edge", v)
                    heapq.heappush(heap, (candidate, u))

        dp[mask] = dist
        choice[mask] = trace

    if src not in dp[full]:
        return None

    selected = set()
    visiting = set()

    def recover(mask, v):
        state = (mask, v)
        if state in visiting:
            return
        visiting.add(state)
        action = choice[mask][v]
        if action[0] == "edge":
            w = action[1]
            selected.add((v, w))
            recover(mask, w)
        elif action[0] == "merge":
            left = action[1]
            recover(left, v)
            recover(mask ^ left, v)
        visiting.remove(state)

    recover(full, src)
    return selected


def search_algorithm(src, dsts, G, num_partitions):
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    # Ignore unusable cost edges rather than allowing Dijkstra comparisons with None.
    invalid = [(u, v) for u, v, data in h.edges(data=True) if _edge_cost(data) is None]
    h.remove_edges_from(invalid)

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    unique_dsts = list(dict.fromkeys(dsts))

    try:
        baseline_paths = _shortest_paths(h, src, unique_dsts)
    except (nx.NetworkXNoPath, nx.NodeNotFound):
        # Preserve the original behavior for malformed/unreachable evaluator inputs.
        baseline_paths = {}
        for dst in unique_dsts:
            try:
                baseline_paths[dst] = nx.dijkstra_path(h, src, dst, weight="cost")
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                baseline_paths[dst] = []

    baseline_edges = _paths_to_edges(baseline_paths)
    selected_edges = baseline_edges

    steiner_edges = _directed_steiner_edges(h, src, unique_dsts)
    if steiner_edges is not None and _edge_union_cost(h, steiner_edges) <= _edge_union_cost(h, baseline_edges):
        selected_edges = steiner_edges
    elif len(unique_dsts) > 7:
        try:
            lengths = nx.single_source_dijkstra_path_length(h, src, weight="cost")
            ordered = sorted(unique_dsts, key=lambda d: lengths.get(d, float("inf")))
            orders = [unique_dsts, list(reversed(unique_dsts)), ordered, list(reversed(ordered))]
            for dst in unique_dsts[:4]:
                orders.append([dst] + [x for x in unique_dsts if x != dst])
            greedy_edges, _ = _greedy_tree(h, src, unique_dsts, orders)
            if greedy_edges is not None and _edge_union_cost(h, greedy_edges) < _edge_union_cost(h, selected_edges):
                selected_edges = greedy_edges
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            pass

    tree_graph = nx.DiGraph()
    tree_graph.add_nodes_from(h.nodes())
    for u, v in selected_edges:
        tree_graph.add_edge(u, v, **G[u][v])

    final_paths = {}
    for dst in unique_dsts:
        try:
            final_paths[dst] = nx.dijkstra_path(tree_graph, src, dst, weight="cost")
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            final_paths[dst] = baseline_paths.get(dst, [])

    for dst in dsts:
        path = final_paths.get(dst, [])
        edges = [[u, v, G[u][v]] for u, v in zip(path, path[1:])]
        for partition in range(bc_topology.num_partitions):
            bc_topology.set_dst_partition_paths(dst, partition, list(edges))

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        self.paths[dst][str(partition)] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)


def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(
            row["src_region"],
            row["dst_region"],
            cost=None,
            throughput=num_vms * row["throughput_sent"] / 1e9,
        )

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    no_cost_pairs = []
    for edge in G.edges.data():
        edge_src, edge_dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((edge_src, edge_dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G

